import sys
sys.path.insert(0, "/home/claude/winesite/scripts/c8")
from common import site

I = "hu"; T = "Tokaj"
def v(slug, name, lat, lon, text):
    return site(I, "tokaj-" + slug, name, "village", lat, lon, text, "precise", "Tokaj PDO settlement", T)
def d(slug, name, lat, lon, text, cls, prod=None, cq="approx"):
    return site(I, slug, name, "lieu_dit", lat, lon, text, cq, cls, T, prod)

VILLAGES = [
v("tarcal", "Tarcal", 48.1298, 21.3456, "Tarcal sits on the south-western foot of Tokaj hill, where loess drapes the volcanic core. It holds some of the region's most storied sites (Mézes Mály, Szarvas, Lónyai, Váti, Kassai), the Tokaj viticulture research station where Zéta and Kabar were bred, the Andrássy manor and Királyudvar's winery in a former royal court. Kikelet's loess Furmints showed how perfumed wines from this side of the hill can be."),
v("tokaj", "Tokaj", 48.1236, 21.4114, "The town that gave the region its name sits at the point of Tokaj hill (Kopasz-hegy, 514 m) where the Bodrog flows into the Tisza. River traffic once carried barrels north to Poland. The Rákóczi cellar under the main square, the Tokaj Museum and wineries such as Dobogó and Hétszőlő keep the town at the centre of the trade, and its southern slopes carry Hétszőlő and Szarvas."),
v("mad", "Mád", 48.1919, 21.2742, "Mád has the densest concentration of historic first-class vineyards in Tokaj: Szent Tamás, Úrágya, Betsek, Király, Nyulászó, Birsalmás, Percze and Danczka all surround the village, on rhyolite, andesite and quartzite. Royal Tokaji, Szepsy, Barta and Holdvölgy are based here, and the restored baroque synagogue recalls the Jewish merchants who ran much of the Tokaji trade until 1944."),
v("tallya", "Tállya", 48.2354, 21.2299, "Tállya, a large market village on the western side of the hills, sits among andesite and rhyolite slopes with dűlők such as Hasznos and Dorgó. Its vineyards were among the Rákóczi family's holdings, and Lajos Kossuth, born in nearby Monok in 1802, was baptised in its Lutheran church. Its wines tend to be firm and spicy."),
v("bodrogkeresztur", "Bodrogkeresztúr", 48.1588, 21.3607, "Bodrogkeresztúr lies on the Bodrog under the eastern face of Tokaj hill. The Lapis vineyard above it, a terraced rhyolite slope, is the source of Királyudvar's best wines, and the village has given its name to several fine Szamorodni. It is also a Hasidic pilgrimage site, home of the grave of the 'Kerestirer Rebbe', Reb Shayele Steiner."),
v("erdobenye", "Erdőbénye", 48.2663, 21.3560, "A forested village in a side valley at the northern edge of the Tokaj hills, Erdőbénye was the region's cooperage centre, making the 136-litre Gönc casks and smaller barrels from local Zemplén oak. Máté Szepsi Laczkó served as pastor here; his memorial house stands on the main street. Béres and others work its cool, high dűlők such as Lőcse, Omlás and Határi."),
v("olaszliszka", "Olaszliszka", 48.2467, 21.4284, "Olaszliszka, on the Bodrog, carries in its name the 'olasz' (Latin, Italian) settlers invited after the Mongol invasion. Szepsi Laczkó Máté taught here before becoming a pastor. The Frenchman Samuel Tinon chose it for his winery, famous for long flor-aged dry Szamorodni, and Attila Homonna's work on the Határi slope helped put the village's cooler sites on the map."),
v("sarospatak", "Sárospatak", 48.3217, 21.5656, "Sárospatak, on the Bodrog in the north-east, was the seat of the Rákóczi princes. Their castle, the Reformed College founded in 1531 (where Comenius taught), and the Rákóczi cellar beneath the town anchor its history. Today it hosts the Pajzos-Megyer winery, and the Megyer hill above Végardó is one of the north's historic vineyards."),
v("satoraljaujhely", "Sátoraljaújhely", 48.3961, 21.6561, "The northernmost Tokaj town sits on the Slovak border, facing Slovenské Nové Mesto, which belonged to it until 1920. On its castle hill lies the Oremus vineyard, source of the legendary 1631 aszú attributed to Szepsi Laczkó Máté and the name that the Vega Sicilia-owned estate took for its brand."),
v("mezozombor", "Mezőzombor", 48.1503, 21.2596, "Mezőzombor, between Mád and Szerencs, is best known as home to Disznókő, the AXA-owned estate whose single block of about 150 ha takes in the Kapi and Dorgó sites. The village's lower, warmer slopes catch botrytis readily, which made it a reliable source of aszú berries."),
v("ratka", "Rátka", 48.2135, 21.2264, "Rátka is a small village west of Mád, resettled by German-speaking Catholic families in the 18th century. Its main slope is the Padi-hegy, an andesite hill whose vineyards make firm, smoky Furmint."),
v("szegi", "Szegi", 48.1988, 21.3816, "Szegi is a small Bodrog-side village between Bodrogkisfalud and Szegilong, with south-facing slopes such as Poklos. Its location on the river makes it a botrytis-friendly spot, and it has drawn several small modern growers."),
v("szegilong", "Szegilong", 48.2191, 21.4002, "Szegilong, on the right bank of the Bodrog north of Szegi, is one of the 27 settlements of the Tokaj PDO and one of the smallest. Its vineyards share the river mists that make the Bodrog side so reliable for noble rot."),
v("bodrogkisfalud", "Bodrogkisfalud", 48.1728, 21.3575, "Bodrogkisfalud is a riverside village under Tokaj hill's north-eastern flank. The Patricius estate restored an 18th-century manor here, and the Csirke-mál slope above the village is a well-known site."),
v("hercegkut", "Hercegkút", 48.3369, 21.5292, "Hercegkút ('Prince's Well') was settled by German Catholic families in the 18th century. Its two cellar rows, Kőporos and Gombos-hegy, with dozens of stone-fronted cellars dug into the hillside, are part of the core zone of the UNESCO Tokaj landscape."),
v("makkoshotyka", "Makkoshotyka", 48.3564, 21.5186, "Makkoshotyka is a small upland village north-west of Sárospatak, at the forested edge of the Zemplén. It is one of the 27 Tokaj settlements, with few but cool vineyard slopes."),
v("vamosujfalu", "Vámosújfalu", 48.2573, 21.4493, "Vámosújfalu ('customs new village') lies on the plain between Olaszliszka and Sárazsadány, its name recalling a medieval toll point. It is one of the quieter Tokaj settlements, with gentle slopes near the Bodrog."),
v("tolcsva", "Tolcsva", 48.2828, 21.4491, "Tolcsva is one of Tokaj's great wine villages, with Oremus's winery and tunnel cellars, the headquarters of the state-owned Grand Tokaj (successor of the old state combine) and a wine museum. Sites such as Kincsem, Petrács and Kútpatka surround it, and noble rot was reportedly known here by 1527."),
v("erdohorvati", "Erdőhorváti", 48.3148, 21.4275, "Erdőhorváti is a forest village high in the Zemplén hills north of Tolcsva. Its few vineyards are among the coolest in the region, and the village is better known for its woods and walking routes than for wine."),
v("bodrogolaszi", "Bodrogolaszi", 48.2877, 21.5176, "Bodrogolaszi, another village named for its medieval Latin settlers, lies just south of Sárospatak. The Pajzos vineyard, one of the two historic estates of the Pajzos-Megyer winery, lies within its boundary."),
v("golop", "Golop", 48.2389, 21.1894, "Golop is a small village at the western margin of the region, between Tállya and Monok, on the edge of the Hernád valley. Its vineyards sit on the outer slopes of the Zemplén volcanic range."),
v("monok", "Monok", 48.2122, 21.1498, "Monok, at the far western rim of the Tokaj PDO, is famous as the birthplace of Lajos Kossuth (1802), leader of the 1848 revolution. Its vineyards face south over the Szerencs plain."),
v("legyesbenye", "Legyesbénye", 48.1602, 21.1496, "Legyesbénye is at the south-western end of the Tokaj crescent, near the Szerencs plain. It is a quiet village with gentle slopes, included among the 27 settlements of the PDO."),
v("bekecs", "Bekecs", 48.1516, 21.1711, "Bekecs, west of Szerencs, is one of the south-western edge villages of the region. Its gentle slopes give softer wines than the steep hills of Mád or Tarcal."),
v("abaujszanto", "Abaújszántó", 48.2787, 21.1855, "Abaújszántó marks the western end of Tokaj where the hills drop into the Hernád valley. Its Sátor-hegy ('Tent hill') and other volcanic slopes are farmed by the biodynamic Pendits estate, one of the region's early organic pioneers."),
v("szerencs", "Szerencs", 48.1634, 21.2011, "Szerencs is the gateway town at the south-western corner of Tokaj. The Rákóczi castle here hosted the 1605 diet that elected István Bocskai prince, and the town now includes Ond, whose Kőporos slope is a respected site. The town is also known for its chocolate factory."),
v("sarazsadany", "Sárazsadány", 48.2634, 21.4942, "Sárazsadány is a small village near the Bodrog between Vámosújfalu and Bodrogolaszi. It is one of the 27 Tokaj settlements, with gentle, botrytis-prone vineyards close to the river."),
]

DULOS = [
d("mezes-maly", "Mézes Mály", 48.1468, 21.3257, "'Honey pot' in old Hungarian, Mézes Mály in Tarcal was ranked a great first growth in the old classifications. About 19 ha of volcanic bedrock under deep loess on a warm south slope; Royal Tokaji owns about 11 ha and bottles both an Aszú and a dry Furmint from it. Its wines are rich and honeyed with a soft, broad texture from the loess.", "Great First Growth (historic)", ["Royal Tokaji", "Királyudvar"]),
d("szarvas", "Szarvas", 48.1062, 21.3797, "Szarvas ('stag') lies on the southern foot of Tokaj hill between Tarcal and Tokaj and was rated a great first growth of the old classification. It was a royal and later Habsburg estate, and today belongs to the state-owned Grand Tokaj. Its loess and andesite give powerful, early-ripening aszú.", "Great First Growth (historic)", ["Grand Tokaj"]),
d("szent-tamas", "Szent Tamás", 48.1914, 21.2929, "Named after St Thomas, this first-class Mád hillside of red nyirok clay and rhyolite tuff makes tense, smoky, saline wines. Szepsy's and the Szent Tamás winery's dry Furmints and Royal Tokaji's Aszú are its best-known bottlings.", "First Growth (historic)", ["Szepsy", "Royal Tokaji", "Szent Tamás Pincészet"]),
d("uragya", "Úrágya", 48.2004, 21.2741, "Úrágya ('the lord's bed') lies on a high, steep slope north of Mád, on quartz-rich, silicified volcanic rock. Szepsy's and Királyudvar's dry Úrágya Furmint 2000 helped launch the dry single-vineyard movement, and the site still makes some of the most austere, long-lived dry wines in Tokaj.", "First Growth (historic)", ["Szepsy", "Királyudvar"]),
d("betsek", "Betsek", 48.1837, 21.3156, "Betsek (also spelled Becsek) is a large first-class site east of Mád toward Bodrogkeresztúr, on rhyolite tuff and clay. Royal Tokaji's 1990 Betsek Aszú was among its first releases, and Dobogó and Szepsy also make wines from it.", "First Growth (historic)", ["Royal Tokaji", "Dobogó", "Szepsy"]),
d("kiraly", "Király", 48.1900, 21.3177, "Király ('king') rises above Mád on rhyolite and red clay. Its steep upper part, Öreg Király ('old king'), was cleared and re-terraced by the Barta family from 2003 and is one of the steepest vineyards in the region; Szepsy also has parcels.", "First Growth (historic)", ["Barta", "Szepsy"]),
d("nyulaszo", "Nyulászó", 48.1857, 21.2877, "Nyulászó ('hare-hunting place') is a first-class Mád site of volcanic clay that Royal Tokaji blends into its Aszú and bottles separately in good years. Its wines tend to be fine and spicy.", "First Growth (historic)", ["Royal Tokaji", "Szepsy"]),
d("birsalmas", "Birsalmás", 48.1957, 21.2702, "Birsalmás ('quince orchard') lies on the western side of Mád. Royal Tokaji counts it among its first growths, and its name matches the quince note that classic Furmint often carries.", "First Growth (historic)", ["Royal Tokaji"]),
d("percze", "Percze", 48.1943, 21.2871, "Percze is a small site close to the village of Mád, on rhyolite tuff; the Szepsy family consider it one of their best plots and named their Mád restaurant after it.", "Mád dűlő", ["Szepsy"]),
d("danczka", "Danczka", 48.1860, 21.2553, "Danczka (Dancka in the official list) sits around the Danczka-tető hilltop west of Mád. Its stony, windy slopes make tight, mineral dry wines, bottled by several of the Mád Circle growers.", "Mád dűlő", ["Szepsy", "Holdvölgy"]),
d("bomboly", "Bomboly", 48.2104, 21.3022, "Bomboly is a cool, elevated site north-east of Mád, with volcanic tuff soils. Its name appears on several modern single-vineyard dry Furmints. Being higher and more exposed, it ripens later than the village slopes and keeps notably bright acidity.", "Mád dűlő"),
d("veresek", "Veresek", 48.1765, 21.3190, "Veresek ('the red ones') takes its name from the reddish volcanic clay of this Mád slope near the Bodrogkeresztúr border. It is a source of concentrated aszú berries.", "Mád dűlő"),
d("hold-volgy", "Hold-völgy", 48.2032, 21.2664, "Hold-völgy ('moon valley') is a sheltered valley site at Mád, and gave its name to the Holdvölgy winery, which works it along with neighbouring first-class sites.", "Mád dűlő", ["Holdvölgy"]),
d("juharos", "Juharos", 48.2059, 21.2911, "Juharos ('maple wood') is a Mád site in the official dűlő list, on volcanic tuff north of the village, producing fresh, mineral Furmint. Its northern position gives slow ripening, which suits dry styles more than aszú in most years.", "Mád dűlő"),
d("kovago", "Kővágó", 48.1943, 21.3087, "Kővágó ('stone-cutter') is a stony Mád dűlő east of the village whose name recalls old quarrying; it makes firm, concentrated Furmint. Cut stone from the hill once went into Mád's houses and cellars, and the soil is correspondingly thin and rocky.", "Mád dűlő"),
d("lapis", "Lapis", 48.1899, 21.3467, "Lapis (Latin for 'stone') is a terraced rhyolite slope above Bodrogkeresztúr. Királyudvar's Lapis Furmint and 6 Puttonyos Aszú made it famous, and the site produces taut, stony wines.", "First Growth (historic)", ["Királyudvar"]),
d("sajgo", "Sajgó", 48.1726, 21.3283, "Sajgó lies on the Bodrogkeresztúr side of the Mád border, on volcanic tuff and clay, and gives powerful aszú berries. The site sits on the gentle saddle where the Mád valley opens toward the Bodrog, so river mist reaches it easily.", "Bodrogkeresztúr dűlő"),
d("bendecz", "Bendecz", 48.1709, 21.3341, "Bendecz is a Bodrogkeresztúr site south of the village center, on mixed volcanic soils, used for both dry and sweet wines by local growers. Like much of Bodrogkeresztúr, it benefits from the morning fogs rising off the river directly below.", "Bodrogkeresztúr dűlő"),
d("kapi", "Kapi", 48.1663, 21.3114, "Kapi is a historic site on the Mezőzombor side of the Mád road, included in Disznókő's estate. In top botrytis years Disznókő bottles a single-vineyard Kapi 6 Puttonyos Aszú.", "Disznókő single vineyard", ["Disznókő"]),
d("disznoko-dulo", "Disznókő", 48.1700, 21.3060, "The Disznókő ('boar's rock') vineyard, first recorded in 1413, takes its name from a large boulder on the slope. It was ranked a first growth in the 18th-century classifications and today forms a single 150 ha block owned by AXA Millésimes.", "First Growth (historic)", ["Disznókő"]),
d("kassai", "Kassai", 48.1370, 21.3580, "Kassai (named after Košice) is a Tarcal site on Kassai-hegy, part loess and part volcanic. Kikelet's Stéphanie Berecz made it known for silky, aromatic dry Furmint and Hárslevelű from loess.", "Tarcal dűlő", ["Kikelet"]),
d("lonyai", "Lónyai", 48.1352, 21.3526, "Lónyai, named after a noble family, is a loess-covered Tarcal slope whose dry Hárslevelű and Furmint from Kikelet are textbook loess wines: floral, round and fine.", "Tarcal dűlő", ["Kikelet"]),
d("vati", "Váti", 48.1257, 21.3631, "Váti is a Tarcal site on the warm, loess-covered southern face of Tokaj hill, worked by Kikelet and others. The loess here is deep and fine, so the wines are perfumed, supple and approachable early, the opposite of Mád's flinty style.", "Tarcal dűlő", ["Kikelet"]),
d("mandulas", "Mandulás", 48.1235, 21.3533, "Mandulás ('almond grove') is a Tarcal loess site on the warm southern side of Tokaj hill. Almond trees once grew between the vines, a sign of how sheltered and warm the slope is. The wines are soft and aromatic, typical of Tokaj hill's loess side.", "Tarcal dűlő"),
d("elohegy", "Előhegy", 48.1427, 21.3504, "Előhegy ('front hill') is a Tarcal hillside facing toward the Bodrog, on volcanic rock with loess patches. Its position on the hill's eastern flank catches the first morning sun and the Bodrog mists alike, a good combination for botrytis.", "Tarcal dűlő"),
d("szentkereszt", "Szentkereszt", 48.1421, 21.3734, "Szentkereszt ('holy cross') lies high on Tokaj hill above Tarcal, a mix of andesite and loess with long views over the Great Plain. It is one of the higher sites on Tokaj hill, so the wines combine loess softness with more lift and acidity.", "Tarcal dűlő"),
d("hetszolo-dulo", "Hétszőlő", 48.1130, 21.3971, "Hétszőlő ('seven vineyards') was assembled from seven parcels by the Garai family in 1502 and later owned by Gáspár Károli, Gábor Bethlen, the Rákóczis and the Habsburgs. Its 55 ha of south-facing slopes on volcanic rock under loess now belong to Michel Reybier's Tokaj-Hétszőlő estate.", "First Growth (historic)", ["Tokaj-Hétszőlő"]),
d("nagy-szolo", "Nagy-szőlő", 48.1114, 21.3933, "Nagy-szőlő ('big vineyard') is a loess site on the southern foot of Tokaj hill next to Hétszőlő. Its sheltered, low position by the Tisza floodplain makes it an early-ripening site with frequent botrytis.", "Tokaj dűlő"),
d("teleki", "Teleki", 48.1090, 21.3874, "Teleki is a site on the southern foot of Tokaj hill near Hétszőlő, on loess-covered volcanic rock. It takes its name from the Teleki noble family, who held land in Tokaj, and shares the warm, loess-covered profile of its neighbour Hétszőlő.", "Tokaj dűlő"),
d("padi", "Padi-hegy", 48.1992, 21.2517, "Padi-hegy at Rátka is an andesite hill west of Mád whose slopes make structured, smoky Furmint. The hill's peak, Nagy-Padi, rises above the village, and its vineyards face south-east over the Mád valley.", "Rátka dűlő"),
d("hasznos", "Hasznos", 48.2527, 21.2281, "Hasznos ('useful') is a Tállya site on andesite and volcanic tuff, known for firm, spicy wines. It lies on the hills north of the village toward Golop, a historically important part of the Rákóczi family's Tállya holdings.", "Tállya dűlő"),
d("koporos-ond", "Kőporos (Ond)", 48.1929, 21.2067, "Kőporos ('stone dust') at Ond, now part of Szerencs, is a stony volcanic hillside whose name describes the powdery weathered rock underfoot. Ond's slopes face south over the Szerencs plain and were valued in the old classifications.", "Szerencs dűlő"),
d("csirke-mal", "Csirke-mál", 48.2003, 21.3525, "Csirke-mál ('chicken slope') in Bodrogkisfalud is a warm, sheltered south-facing site; 'mál' is an old word for a sunny hillside. Its warmth makes it a dependable source of ripe, botrytised fruit.", "Bodrogkisfalud dűlő"),
d("poklos", "Poklos", 48.2039, 21.3823, "Poklos is a Szegi site above the Bodrog, whose name hints at its hot ('hellish') sun exposure. The steep slope faces south over the river, so it gets both heat and the moisture that brings noble rot.", "Szegi dűlő"),
d("locse", "Lőcse", 48.2750, 21.3752, "Lőcse, named after the Upper Hungarian town of Levoča, is a high Erdőbénye site of rhyolite tuff and loess where Béres makes fresh, mineral dry wines.", "Erdőbénye dűlő", ["Béres"]),
d("omlas", "Omlás", 48.2780, 21.3619, "Omlás ('landslide') is a steep Erdőbénye slope of weathered volcanic rock in the cool northern part of the region. Béres works it for dry Furmint with bright acidity, a reminder that the forested north of the region is markedly cooler than the south.", "Erdőbénye dűlő", ["Béres"]),
d("hatari", "Határi", 48.2711, 21.3857, "Határi ('border') sits on the line between Erdőbénye and Olaszliszka. Attila Homonna's dry Furmints from about 2005 drew attention to this forgotten, cool, stony slope.", "Erdőbénye dűlő", ["Homonna"]),
d("csontos", "Csontos", 48.2755, 21.4052, "Csontos ('bony') is an Olaszliszka site whose name describes its stony, skeletal volcanic soil. Wines from such thin, rocky ground are typically tight and mineral, best after some years in bottle.", "Olaszliszka dűlő"),
d("kincsem", "Kincsem", 48.2759, 21.4696, "Kincsem ('my treasure') is a Tolcsva vineyard best known through Grand Tokaj and other Tolcsva producers; the name is shared with Hungary's legendary unbeaten racehorse.", "Tolcsva dűlő"),
d("petracs", "Petrács", 48.2932, 21.4558, "Petrács is a historic Tolcsva site belonging largely to Oremus, on volcanic soils above the village. The slope rises steeply behind Tolcsva and has long been prized for aszú berries.", "Tolcsva dűlő", ["Oremus"]),
d("kutpatka", "Kútpatka", 48.2795, 21.4190, "Kútpatka ('well's horseshoe') is a Tolcsva site whose fruit goes into Oremus's wines. It is a horseshoe-shaped hollow named for a well, and its sheltered bowl concentrates warmth.", "Tolcsva dűlő", ["Oremus"]),
d("pajzos-dulo", "Pajzos", 48.2885, 21.4875, "The Pajzos vineyard lies in Bodrogolaszi just south of Sárospatak. Rated first class in 1772, its 107-ha estate was bought in 1991 by Jean-Louis Laborde's French group and is now the core of Pajzos-Megyer; its 1993 Esszencia earned a perfect score from the Wine Advocate.", "First Growth (historic)", ["Pajzos-Megyer"]),
d("megyer", "Megyer", 48.3491, 21.5737, "Megyer is a historic 110-ha vineyard on the hill above Végardó at Sárospatak. The French insurer GAN won it in the 1992 privatisation, and it was later merged with Pajzos. Its cooler northern position gives fresher, more aromatic wines.", "Sárospatak dűlő", ["Pajzos-Megyer"]),
d("oremus-dulo", "Oremus", 48.3799, 21.6357, "Oremus ('let us pray') is the vineyard on the castle hill of Sátoraljaújhely, owned by the Rákóczis. Legend makes it the source of Szepsi Laczkó Máté's first aszú (1631), and it was rated primae classis in 1772. Vega Sicilia's Tolcsva estate took its name.", "First Growth (historic)", ["Oremus"]),
]

ESTATES = [
site(I, "royal-tokaji", "Royal Tokaji", "estate", 48.1929, 21.2778, "Founded in 1990 by Hugh Johnson, Danish winemaker Peter Vinding-Diers and about 60 Mád growers, Royal Tokaji was the first Western joint venture of the post-Communist era. It bought grapes until 1993 and now farms about 100 to 112 ha, including Mézes Mály, Szent Tamás, Betsek, Nyulászó and Birsalmás, which it labels with their historic first-growth ranks.", "precise", "Winery, Mád", T, ["Royal Tokaji"]),
site(I, "disznoko", "Disznókő", "estate", 48.1666, 21.3026, "AXA Millésimes bought Disznókő ('boar's rock', first recorded 1413) in 1992 and rebuilt the winery beside the old press house. The estate is a single 150 ha block on a south-facing volcanic slope, planted with Furmint, Hárslevelű, Zéta and Sárgamuskotály. Its Aszú, Kapi single vineyard and '1413' sweet wine are benchmarks.", "precise", "Winery, Mezőzombor", T, ["Disznókő"]),
site(I, "oremus", "Oremus (Tolcsva winery)", "estate", 48.2868, 21.4434, "The Álvarez family of Vega Sicilia founded Tokaj Oremus in 1993 at Tolcsva. The wines age in old tunnel cellars cut into the rock under the winery. Its dry Mandolás Furmint (since 2000) helped launch the dry wine revival, while its Aszú and Eszencia are among the most polished in the region.", "precise", "Winery, Tolcsva", T, ["Oremus"]),
site(I, "pajzos-megyer", "Pajzos-Megyer (Sárospatak)", "chateau", 48.3217, 21.5656, "The French investment group CFGVT, led by Jean-Louis Laborde, began buying in Tokaj in 1991; GAN won the Megyer vineyard in 1992. Laborde merged both into Pajzos Zrt around 2000. The Pajzos Esszencias of 1993 and 1999 both received 100 points from the Wine Advocate. The winery is on Nagy Lajos utca in Sárospatak.", "approx", "Winery, Sárospatak (formerly Château Pajzos and Château Megyer)", T, ["Pajzos-Megyer"]),
site(I, "szepsy", "Szepsy", "estate", 48.1925, 21.2770, "István Szepsy, from a family of growers that traces its Tokaj roots to the 1500s, released his first Aszú in 1991 and, from the 2000 vintage, the dry single-vineyard Furmints (Szent Tamás, Úrágya, Betsek, Király and others) that redefined Tokaj. The family farms about 52 ha around Mád; his 6 Puttonyos 1999 is a Decanter 'wine legend'.", "approx", "Family estate, Mád", T, ["Szepsy"]),
site(I, "kiralyudvar", "Királyudvar", "estate", 48.1290, 21.3445, "Királyudvar ('royal court') occupies a historic royal court building in Tarcal. Anthony Hwang, owner of Domaine Huet in Vouvray, bought it in 1997; Zoltán Demeter and István Szepsy shaped its early wines. It farms biodynamically, and its Lapis vineyard Aszú and Cuvée Ilona late harvest are classics.", "approx", "Winery, Tarcal", T, ["Királyudvar"]),
site(I, "dobogo", "Dobogó", "estate", 48.1253, 21.4045, "Dobogó is a small winery in the old town of Tokaj founded by Izabella Zwack, of the Unicum liqueur family, in the mid-1990s. It makes dry Furmint from Betsek, Aszú and the late-harvest Mylitta from first-class sites.", "approx", "Winery, Tokaj town", T, ["Dobogó"]),
site(I, "patricius", "Patricius", "estate", 48.1917, 21.3609, "Patricius was founded in 2000 by the Kékessy family in a restored 18th-century manor at Bodrogkisfalud. It owns about 85 ha in first-class sites and is known for dry Furmint, Katinka late harvest and long-aged Aszú.", "precise", "Winery, Bodrogkisfalud", T, ["Patricius"]),
site(I, "grand-tokaj", "Grand Tokaj", "estate", 48.2828, 21.4491, "Grand Tokaj is the state-owned successor of the Communist-era Tokaj combine and the later Tokaj Kereskedőház, based at Tolcsva. It buys grapes from thousands of small growers and remains the region's largest producer, exporting to more than 30 countries. Its holdings include the great first growth Szarvas.", "approx", "State winery, Tolcsva", T, ["Grand Tokaj"]),
site(I, "barta", "Barta", "estate", 48.1927, 21.2778, "Károly Barta's family winery in Mád restored the abandoned, terraced Öreg Király ('old king') vineyard from 2003, one of the steepest slopes in Tokaj. The winery occupies an old Rákóczi-era mansion in the village.", "approx", "Family estate, Mád", T, ["Barta"]),
site(I, "samuel-tinon", "Samuel Tinon", "estate", 48.2467, 21.4284, "Samuel Tinon, from a Sainte-Croix-du-Mont winemaking family near Bordeaux, came to Tokaj in 1991 and settled at Olaszliszka. He is best known for reviving dry Szamorodni aged for years under a veil of yeast (flor), as well as long-macerated Aszú.", "approx", "Family estate, Olaszliszka", T, ["Samuel Tinon"]),
site(I, "hetszolo", "Tokaj-Hétszőlő", "estate", 48.1255, 21.4080, "Tokaj-Hétszőlő owns 55 ha of the historic Hétszőlő vineyard on Tokaj hill. The French group GMF bought it in 1991; Michel Reybier, owner of Cos d'Estournel, has owned it since 2009. It is farmed organically and runs the Rákóczi cellar in Tokaj town for tastings.", "precise", "Estate (cellar in Tokaj town)", T, ["Tokaj-Hétszőlő"]),
site(I, "holdvolgy", "Holdvölgy", "estate", 48.1904, 21.2809, "Holdvölgy is a Mád estate founded in the 2000s with vineyards in Hold-völgy and neighbouring first-class sites. Its labyrinthine cellar under the village is used for tastings and ageing.", "precise", "Winery, Mád", T, ["Holdvölgy"]),
site(I, "kikelet", "Kikelet", "estate", 48.1277, 21.3496, "Kikelet ('springtime') is the small Tarcal estate of Stéphanie Berecz, who came from Bordeaux to work at Disznókő, and her husband Zsolt. Their dry Furmint and Hárslevelű from the loess sites Lónyai, Váti and Kassai showed how fine loess wines can be.", "precise", "Family estate, Tarcal", T, ["Kikelet"]),
site(I, "beres", "Béres", "estate", 48.2743, 21.3754, "Béres farms about 45 ha in the cool northern sites around Erdőbénye, including Lőcse, Diókút and Omlás. Its winery sits among the vines above the village.", "precise", "Estate, Erdőbénye", T, ["Béres"]),
]

CELLARS = [
site(I, "rakoczi-cellar-sarospatak", "Rákóczi Cellar, Sárospatak", "cellar", 48.3164, 21.5673, "Beneath the Rákóczi castle in Sárospatak runs a cellar labyrinth of several branches cut into volcanic tuff, used by the princes to store the wine of their Hegyalja estates. Their Tokaji served as a diplomatic gift, notably to Louis XIV. The castle and cellar are now a museum and tasting venue.", "precise", "Historic princely cellar", T),
site(I, "rakoczi-castle-sarospatak", "Rákóczi Castle, Sárospatak", "historic", 48.3156, 21.5689, "The Renaissance castle on the Bodrog was the seat of the Rákóczi princes, owners of great Tokaj vineyards. Zsuzsanna Lorántffy lived here, and Ferenc II Rákóczi led the 1703 to 1711 war of independence from these lands, using Tokaji as diplomatic currency.", "precise", "Historic site", T),
site(I, "rakoczi-cellar-tokaj", "Rákóczi Cellar, Tokaj", "cellar", 48.1255, 21.4080, "This cellar under Tokaj's main square, beside the church, dates from the early 15th century. Its knights' hall (28 m long, 10 m wide, 5 m high) is said to be the largest underground hall in the region. Its walls are coated with black cellar mould, and it is used today for tastings.", "precise", "Historic cellar", T, ["Tokaj-Hétszőlő"]),
site(I, "tokaj-museum", "Tokaj Museum", "museum", 48.1266, 21.4083, "The Tokaj Museum occupies an 18th-century Greek merchant's house in Tokaj town. Greek traders were key middlemen in the 18th-century Tokaji trade. Its exhibits cover the history of Tokaji wine, coopering and the town's Greek, Jewish and Hungarian communities.", "precise", "Museum", T),
site(I, "hercegkut-koporos-cellars", "Kőporos cellar row, Hercegkút", "cellar", 48.3400, 21.5247, "Two streets of cellars dug into the hill above Hercegkút (Kőporos and Gombos-hegy), most with small stone or plastered fronts, form part of the core zone of the UNESCO Tokaj landscape. They show the small-grower cellar culture of the German-speaking settlers.", "precise", "UNESCO core zone cellar row", T),
site(I, "szepsi-laczko-memorial", "Szepsi Laczkó Máté Memorial House", "historic", 48.2655, 21.3552, "In Erdőbénye a small memorial house honours Máté Szepsi Laczkó (c. 1576 to 1632/33), the Reformed pastor credited by legend with the first aszú. Historians doubt the claim, since his own chronicle never mentions aszú, but the story remains central to Tokaj's identity.", "precise", "Historic site", T),
site(I, "mad-synagogue", "Mád Synagogue", "historic", 48.1961, 21.2775, "This late-18th-century baroque synagogue in Mád, restored in the 2000s, recalls the Jewish families who dominated the Tokaji trade, produced kosher wine for Polish and Russian markets and owned many cellars until the Holocaust.", "precise", "Historic site", T),
site(I, "tokaj-landscape", "Tokaj Wine Region Historic Cultural Landscape (UNESCO)", "landscape", 48.1202, 21.3818, "UNESCO inscribed the Tokaj landscape in 2002, with a core area of 13,255 ha and a buffer of 74,879 ha. It recognises a living tradition of viticulture and winemaking, with its pattern of vineyards, villages and rock-cut cellars. The point marks the summit of Tokaj hill (Kopasz-hegy, 514 m).", "precise", "UNESCO World Heritage Site (2002)", T),
]

SITES = VILLAGES + DULOS + ESTATES + CELLARS
